using NUnit.Framework;using UnityEngine;using UnityEngine.AI;using UnityEditor.SceneManagement;
namespace VRFPS.Tests {public class AuthoredNavigationTests {
 [TestCase("Room")] [TestCase("Classroom")] public void NoInvisibleDuplicateFurnitureCollision(string name){try{EditorSceneManager.OpenScene("Assets/VRFPS/Scenes/Maps/"+name+".unity");var map=Object.FindFirstObjectByType<MapRoot>();foreach(var c in map.GetComponentsInChildren<Collider>())if(c.gameObject.layer==LayerMask.NameToLayer("WorldSolid"))Assert.That(c.transform.IsChildOf(map.collisionRoot),Is.True,c.name);}finally{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);}}
 [Test] public void SchoolFrontOpenStripConnectsToPlayer(){try {EditorSceneManager.OpenScene("Assets/VRFPS/Scenes/Maps/Classroom.unity");var map=Object.FindFirstObjectByType<MapRoot>();foreach(float x in new[]{-8f,-4f,0f,4f,8f}){var p=new Vector3(x,0,2.4f);Assert.That(NavMesh.SamplePosition(p,out var h,.15f,NavMesh.AllAreas),Is.True,"Open strip missing at "+p);var path=new NavMeshPath();Assert.That(NavMesh.CalculatePath(h.position,map.playerSpawn.position,NavMesh.AllAreas,path),Is.True);Assert.That(path.status,Is.EqualTo(NavMeshPathStatus.PathComplete),"Disconnected "+p);}}finally{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);}}
}}
